findings.remediation_template:
ingress {
  from_port   = 22
  to_port     = 22
  protocol    = "tcp"
  cidr_blocks = ["10.0.0.0/8"]
}

resource "aws_s3_bucket_acl" "sensitive_data" {
  bucket = aws_s3_bucket.sensitive_data.id
  acl    = "private"
}

Statement = [{
  Effect   = "Allow"
  Action   = ["s3:GetObject", "s3:PutObject"]
  Resource = ["arn:aws:s3:::corp-app-logs-prod/*"]
}]

resource "aws_s3_bucket_server_side_encryption_configuration" "sensitive_data" {
  bucket = aws_s3_bucket.sensitive_data.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.app_key.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "sensitive_data" {
  bucket = aws_s3_bucket.sensitive_data.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "sensitive_data" {
  bucket        = aws_s3_bucket.sensitive_data.id
  target_bucket = aws_s3_bucket.app_logs.id
  target_prefix = "s3-access/"
}
